    private static RequestSpec listRequest(String companyId, ChatListParams params) {
        QueryString query = new QueryString();
        if (params != null) {
            query.add("cursor", params.cursor().orElse(null));
            query.add("limit", params.limit().orElse(null));
        }
        return RequestSpec.of("GET", "/v1/companies/{co}/chat", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat")
            .query(query);
    }

    private static RequestSpec createRequest(String companyId, ChatMessageRequest body, boolean stream) {
        return RequestSpec.of("POST", "/v1/companies/{co}/chat", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat")
            .jsonBodyWithStream(body, stream)
            .idempotent("Idempotency-Key");
    }

    private static RequestSpec countTokensRequest(String companyId, ChatTokenCountRequest body) {
        return RequestSpec.of("POST", "/v1/companies/{co}/chat/count-tokens", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/count-tokens")
            .jsonBody(Objects.requireNonNull(body, "body"));
    }

    private static RequestSpec listMentionsRequest(String companyId, ChatListMentionsParams params) {
        QueryString query = new QueryString();
        if (params != null) {
            query.add("limit", params.limit().orElse(null));
            query.add("q", params.q().orElse(null));
            query.add("types", params.types().orElse(null));
        }
        return RequestSpec.of("GET", "/v1/companies/{co}/chat/mentions", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/mentions")
            .query(query);
    }

    private static RequestSpec listSuggestionsRequest(String companyId, ChatListSuggestionsParams params) {
        QueryString query = new QueryString();
        if (params != null) {
            query.add("lang", params.lang().orElse(null));
        }
        return RequestSpec.of("GET", "/v1/companies/{co}/chat/suggestions", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/suggestions")
            .query(query);
    }

    private static RequestSpec getRequest(String companyId, String id) {
        return RequestSpec.of("GET", "/v1/companies/{co}/chat/{id}", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id));
    }

    private static RequestSpec updateRequest(String companyId, String id, ChatDialogPatch body) {
        return RequestSpec.of("PATCH", "/v1/companies/{co}/chat/{id}", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id))
            .jsonBody(Objects.requireNonNull(body, "body"));
    }

    private static RequestSpec deleteRequest(String companyId, String id) {
        return RequestSpec.of("DELETE", "/v1/companies/{co}/chat/{id}", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id));
    }

    private static RequestSpec answerRequest(String companyId, String id, ChatAnswerRequest body, boolean stream) {
        return RequestSpec.of("POST", "/v1/companies/{co}/chat/{id}/answer", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id) + "/answer")
            .jsonBodyWithStream(body, stream);
    }

    private static RequestSpec listEventsRequest(String companyId, String id, ChatListEventsParams params) {
        QueryString query = new QueryString();
        if (params != null) {
            query.add("turn", params.turn().orElse(null));
        }
        return RequestSpec.of("GET", "/v1/companies/{co}/chat/{id}/events", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id) + "/events")
            .query(query);
    }

    private static RequestSpec stopRequest(String companyId, String id) {
        return RequestSpec.of("POST", "/v1/companies/{co}/chat/{id}/stop", "/v1/companies/" + PathSegments.encode("companyId", companyId) + "/chat/" + PathSegments.encode("id", id) + "/stop");
    }

